using Forge.Kernel.Access;
using Forge.Kernel.Security;

namespace Forge.Engineering.Contracts;

/// <summary>Exact generated bytes in Engineering's existing content-addressed file store and shared transaction.</summary>
public interface IGeneratedDocumentContentStore
{
    Task<DocumentFileInfo> StoreAsync(byte[] bytes, string actor, DateTimeOffset at, CancellationToken ct);
    Task<byte[]?> ReadAsync(string sha256, CancellationToken ct);
}

public sealed record GeneratedContentAccess(bool KnownBinding, bool IsPermitted,
    IReadOnlyList<ResourceRef> Resources, AuthorizationDecision? Denial = null, ResourceRef? DeniedResource = null);

/// <summary>External generated-content owners use current and recorded source authority. A known denied binding never falls back to creator/orphan access.</summary>
public interface IGeneratedContentOwnerAccess
{
    Task<GeneratedContentAccess> CheckAsync(IKernelUnitOfWork uow, ForgePrincipal principal, string sha256, CancellationToken ct);
}
